+{% extends 'dashboard.html' %}
+{% load static %}
+{% load humanize %}
+
+{% block title %}
+Monthly Billing Report
+{% endblock title %}
+
+{% block style %}
+<style>
+    .button2 {
+        background-color: var(--main-color);
+        color: white;
+        padding: 8px 30px;
+        border: none;
+        border-radius: 15px;
+        box-shadow: inset 0px -8px 7px 0 rgb(0 0 0 / 24%), inset 0px 5px 7px 0 rgb(255 255 255 / 52%), 0px 6px 6px 0 rgb(0 0 0 / 19%);
+        transition: all ease 0.3s;
+        margin-bottom: 10px;
+        margin-left: 10px;
+        width: 200px;
+        font-weight: 600;
+        font-size: 16px;
+    }
+
+    .btn.button2:hover {
+        background: var(--main-color);
+        color: #ffffff;
+        border-radius: 30px;
+        box-shadow: inset 0px -8px 7px 0 rgba(0, 0, 0, 0.39), inset 0px 5px 7px 0 #e6ecebd8, 0px 6px 6px 0 rgb(0 0 0 / 19%);
+        transition: all ease-in 0.5s;
+    }
+
+    .btn.button2:focus {
+        background: var(--main-color);
+        color: #ffffff;
+        border-radius: 30px;
+        box-shadow: inset 0px 4px 7px 0 rgba(0, 0, 0, 0.274), inset 0px -5px 7px 0 #e6ecebd8;
+        transition: all 0.1s;
+        outline: none;
+    }
+
+    .form-select,
+    .form-control {
+        width: 140px;
+        margin-bottom: 10px;
+        display: inline-block;
+        margin-right: 10px;
+        font-size: 14px;
+        padding: 6px 10px;
+        border-radius: 6px;
+        border: 1px solid #ced4da;
+        box-sizing: border-box;
+        transition: border-color 0.3s ease;
+    }
+
+    .form-select:focus,
+    .form-control:focus {
+        border-color: var(--main-color);
+        outline: none;
+        box-shadow: 0 0 5px rgba(0, 95, 115, 0.5);
+    }
+
+    .table-scrolls {
+        max-height: 520px;
+        overflow-y: auto;
+        position: relative;
+        border: 1px solid #dee2e6;
+        border-radius: 8px;
+        box-shadow: 0 2px 8px rgb(0 0 0 / 0.1);
+        background-color: #fff;
+    }
+
+    table {
+        border-collapse: separate !important;
+        border-spacing: 0;
+        width: 100%;
+        min-width: 700px;
+        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+        font-size: 14px;
+    }
+
+    .table thead th {
+        position: sticky;
+        top: 0;
+        background-color: #005F73;
+        color: white;
+        height: 50px;
+        vertical-align: middle;
+        padding: 12px 8px;
+        white-space: nowrap;
+        word-break: normal;
+        text-align: center;
+        z-index: 11;
+        box-shadow: inset 0 -3px 5px rgb(0 0 0 / 0.15);
+    }
+
+    .table thead th:first-child {
+        text-align: left;
+        padding-left: 15px;
+        max-width: 280px;
+        white-space: nowrap;
+        overflow: hidden;
+        text-overflow: ellipsis;
+    }
+
+    .table tbody td {
+        padding: 10px 8px;
+        border-top: 1px solid #dee2e6;
+        vertical-align: middle;
+        white-space: nowrap;
+        text-align: center;
+    }
+
+    .table tbody td:first-child {
+        text-align: left;
+        max-width: 280px;
+        white-space: nowrap;
+        overflow: hidden;
+        text-overflow: ellipsis;
+        padding-left: 15px;
+    }
+
+    .table tbody tr:nth-child(even) {
+        background-color: #f9fafb;
+    }
+
+    .table tbody tr:hover {
+        background-color: #d9f0f7;
+        transition: background-color 0.3s ease;
+        cursor: default;
+    }
+
+    .table tfoot td {
+        position: sticky;
+        bottom: 0;
+        background-color: #f1f3f5;
+        font-weight: 700;
+        border-top: 2px solid #005F73;
+        padding: 12px 8px;
+        text-align: center;
+        z-index: 12;
+        white-space: nowrap;
+    }
+
+    .table tfoot td:first-child {
+        text-align: left;
+        padding-left: 15px;
+        white-space: nowrap;
+        overflow: hidden;
+        text-overflow: ellipsis;
+    }
+
+    @media (max-width: 768px) {
+        .form-select,
+        .form-control {
+            width: 100%;
+            margin-bottom: 8px;
+        }
+        .table-scrolls {
+            max-height: 400px;
+        }
+        table {
+            font-size: 13px;
+            min-width: 100%;
+        }
+    }
+</style>
+{% endblock style %}
+
+
+{% block billreportcopy %}
+
+{% include 'reportstabs.html' %}
+<div class="container-fluid mt-4">
+    <h1 class="text-center mb-4">Bill Report</h1>
+
+    <!-- Date filter form -->
+    <form method="get" class="d-flex flex-wrap align-items-center justify-content-center mb-4">
+        <select name="start_month" class="form-select">
+            {% comment %} <option value="">Start Month</option> {% endcomment %}
+            {% for number, name in months_n %}
+            <option value="{{ number }}" {% if number == start_month %}selected{% endif %}>
+                {{ name }}
+            </option>
+            {% endfor %}
+        </select>
+        <input type="number" name="start_year" class="form-control" placeholder="Start Year" value="{{ start_year }}" />
+
+        <select name="end_month" class="form-select">
+            {% comment %} <option value="">End Month</option> {% endcomment %}
+            {% for number, name in months_n %}
+            <option value="{{ number }}" {% if number == end_month %}selected{% endif %}>
+                {{ name }}
+            </option>
+            {% endfor %}
+        </select>
+        <input type="number" name="end_year" class="form-control" placeholder="End Year" value="{{ end_year }}" />
+
+        <button type="submit" class="btn button2">Filter</button>
+    </form>
+
+    <!-- Scrollable section with only data rows -->
+    <div class="table-responsive table-scrolls">
+    <table class="table table-bordered text-center table-hover table-sm mb-0">
+        <thead>
+        <tr>
+            <th class="text-start" style="max-width: 200px;">Consumer Names</th>
+            {% for month in months_list %}
+            <th>{{ month }}</th>
+            {% endfor %}
+        </tr>
+        </thead>
+        <tbody>
+        {% for row in table_data %}
+        <tr>
+            <td class="text-start"
+                style="max-width: 200px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
+            {{ row.0 }}
+            </td>
+            {% for value in row|slice:"1:" %}
+            <td>{{ value }}</td>
+            {% endfor %}
+        </tr>
+        {% endfor %}
+        </tbody>
+        <tfoot>
+        <tr class="fw-bold table-primary">
+            {% for value in total_row %}
+            <td>{{ value }}</td>
+            {% endfor %}
+        </tr>
+        </tfoot>
+    </table>
+    </div>
+
+
+
+    <div class="text-center my-4">
+        <a href="?export=true
+            {% if start_month %}&start_month={{ start_month }}{% endif %}
+            {% if start_year %}&start_year={{ start_year }}{% endif %}
+            {% if end_month %}&end_month={{ end_month }}{% endif %}
+            {% if end_year %}&end_year={{ end_year }}{% endif %}" class="btn btn-success px-4 py-2">
+            Download Excel Report
+        </a>
+    </div>
+
+    
+</div>
+{% endblock billreportcopy %}
